// Python string semantics that differ from JavaScript's, for ported code that
// must give byte-identical results. Each helper is golden-tested against
// Python output (tests/fixtures/python_strings_golden.json, generated by
// parity-tools/golden/python_strings.py), and numeric helpers golden-tested
// with tests/fixtures/risk_golden.json (parity-tools/golden/risk_cases.py).

import { PythonError } from './pythonJson.js';

// Python str.isspace() is true for exactly these code points (Python 3.12,
// Unicode 15.0). Compared with JS trim(): Python also strips U+001C–U+001F
// and U+0085, and does NOT strip U+FEFF (byte-order mark).
const PY_WHITESPACE =
  '\\t\\n\\x0B\\x0C\\r\\x1C-\\x20\\x85\\xA0\\u1680\\u2000-\\u200A\\u2028\\u2029\\u202F\\u205F\\u3000';
const LEADING = new RegExp(`^[${PY_WHITESPACE}]+`, 'u');
const TRAILING = new RegExp(`[${PY_WHITESPACE}]+$`, 'u');

/**
 * Python `str.strip()` with no arguments.
 *
 * @param {string} value
 * @returns {string}
 */
export function pyStrip(value) {
  return value.replace(LEADING, '').replace(TRAILING, '');
}

/**
 * Python `str.lower()`. JS toLowerCase() applies the same Unicode full
 * lower-case mapping (including 'İ' → 'i̇' and the context-sensitive final
 * sigma); the golden test checks every code point Python lower-cases.
 *
 * @param {string} value
 * @returns {string}
 */
export function pyLower(value) {
  return value.toLowerCase();
}

// ─── Numbers (the seriousness rules) ───

// float() maps every non-ASCII whitespace character to a space and every
// Unicode decimal digit (category Nd) to its ASCII digit, keeps ASCII as is,
// then strips only ASCII whitespace. So '\u2003 0.9' parses but '\x1c0.9' doesn't.
// Python parity: CPython Objects/unicodeobject.c _PyUnicode_TransformDecimalAndSpaceToASCII
const NON_ASCII_SPACE = /^[\x85\xA0\u1680\u2000-\u200A\u2028\u2029\u202F\u205F\u3000]$/u;
const DECIMAL_DIGIT = /^\p{Nd}$/u;
const FLOAT_LITERAL =
  /^[+-]?(?:(?:[0-9](?:_?[0-9])*)?\.[0-9](?:_?[0-9])*|[0-9](?:_?[0-9])*\.?)(?:[eE][+-]?[0-9](?:_?[0-9])*)?$/;
const SPECIAL = /^([+-]?)(inf|infinity|nan)$/i;

/**
 * The value of a Unicode decimal digit. Unicode assigns every run of Nd
 * characters as consecutive 0-9 sequences, so the value is the position
 * within the run, modulo 10.
 *
 * @param {number} cp a code point in category Nd
 * @returns {number}
 */
export function decimalDigitValue(cp) {
  let start = cp;
  while (DECIMAL_DIGIT.test(String.fromCodePoint(start - 1))) start -= 1;
  return (cp - start) % 10;
}

/** The string float()/int() actually parse: Unicode digits → ASCII, Unicode spaces → ' ', ASCII stripped. */
function toAsciiNumber(text) {
  let ascii = '';
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp < 127) ascii += ch;
    else if (NON_ASCII_SPACE.test(ch)) ascii += ' ';
    else if (DECIMAL_DIGIT.test(ch)) ascii += String(decimalDigitValue(cp));
    else ascii += '?'; // never valid
  }
  return ascii.replace(/^[ \t\n\v\f\r]+|[ \t\n\v\f\r]+$/g, '');
}

function floatFromString(text) {
  const s = toAsciiNumber(text);
  const special = SPECIAL.exec(s);
  if (special) return special[2].toLowerCase() === 'nan' ? NaN : special[1] === '-' ? -Infinity : Infinity;
  if (!FLOAT_LITERAL.test(s)) throw new PythonError('ValueError', 'could not convert string to float');
  return Number(s.replaceAll('_', '')); // both correctly rounded; overflow → ±inf like Python
}

/**
 * Python `float(value)` for the values pyJsonLoads produces.
 *
 * @param {unknown} value float (number), int (BigInt), bool, string, or anything else
 * @returns {number}
 * @throws {PythonError} ValueError (bad string), OverflowError (int too large),
 *   TypeError (None, list, dict)
 */
export function pyFloat(value) {
  if (typeof value === 'number') return value;
  if (typeof value === 'boolean') return value ? 1 : 0;
  if (typeof value === 'bigint') {
    const n = Number(value); // rounds to nearest, ties to even, as int.__float__
    if (!Number.isFinite(n)) throw new PythonError('OverflowError', 'int too large to convert to float');
    return n;
  }
  if (typeof value === 'string') return floatFromString(value);
  throw new PythonError('TypeError', 'float() argument must be a string or a real number');
}

/**
 * Python `min(a, b)` / `max(a, b)`: the first argument wins unless the second
 * compares strictly smaller / larger. Any comparison with NaN is false, so
 * `min(1.0, nan)` is 1.0 (JS Math.min gives NaN), and `max(0.0, -0.0)` is 0.0.
 */
export const pyMin = (a, b) => (b < a ? b : a);
export const pyMax = (a, b) => (b > a ? b : a);

/**
 * Python `f"{x:.{digits}f}"`: the exact binary value rounded half-to-even
 * (JS toFixed rounds exact ties up: 0.125 → '0.13', Python '0.12'), no
 * exponent form for large values, '-0.00' for negative zero.
 *
 * @param {number} x
 * @param {number} digits
 * @returns {string}
 */
export function pyFormatFixed(x, digits) {
  if (Number.isNaN(x)) return 'nan';
  if (!Number.isFinite(x)) return x > 0 ? 'inf' : '-inf';
  const sign = x < 0 || Object.is(x, -0) ? '-' : '';
  // x = mantissa · 2^exponent exactly.
  const view = new DataView(new ArrayBuffer(8));
  view.setFloat64(0, Math.abs(x));
  const bits = view.getBigUint64(0);
  const biased = Number((bits >> 52n) & 0x7ffn);
  const fraction = bits & ((1n << 52n) - 1n);
  const mantissa = biased === 0 ? fraction : fraction | (1n << 52n);
  const exponent = biased === 0 ? -1074 : biased - 1075;
  // Scaled value mantissa · 10^digits · 2^exponent, rounded half-to-even to an integer.
  const numerator = mantissa * 10n ** BigInt(digits);
  let scaled;
  if (exponent >= 0) {
    scaled = numerator << BigInt(exponent);
  } else {
    const denominator = 1n << BigInt(-exponent);
    scaled = numerator / denominator;
    const twice = 2n * (numerator % denominator);
    if (twice > denominator || (twice === denominator && scaled % 2n === 1n)) scaled += 1n;
  }
  const text = scaled.toString().padStart(digits + 1, '0');
  const whole = text.slice(0, text.length - digits);
  return digits > 0 ? `${sign}${whole}.${text.slice(-digits)}` : `${sign}${whole}`;
}

/**
 * Python `int(text)` for a string (base 10): optional sign, digits with
 * single underscores between them, Unicode digits and surrounding whitespace
 * as float() allows. Used for SMTP_PORT (views.py:240).
 *
 * @param {string} text
 * @returns {number}
 * @throws {PythonError} ValueError
 */
export function pyIntFromString(text) {
  const s = toAsciiNumber(text);
  if (!/^[+-]?[0-9](?:_?[0-9])*$/.test(s))
    throw new PythonError('ValueError', 'invalid literal for int() with base 10');
  return Number(s.replaceAll('_', ''));
}
